package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.access.oauthclient.domain.AllowedLoginRedirects;

class AllowedLoginRedirectsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed login redirects of oauth client ")
  void test_allowed_login_redirects_v_o_builder() {
    Assertions
        .assertTrue(AllowedLoginRedirectsVO.tryFrom(null).getAllowedLoginRedirects().isEmpty());
    List<AllowedLoginRedirects> list = List.of();
    Assertions.assertEquals(list, AllowedLoginRedirectsVO.from(list).getAllowedLoginRedirects());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedLoginRedirectsVO.tryFrom(falingInstance));
    Assertions.assertEquals(
        "[" + List.of(AllowedLoginRedirects.builder().uid("one").url("one").version(1).build())
            + "]",
        AllowedLoginRedirectsVO
            .from(List.of(AllowedLoginRedirects.builder().uid("one").url("one").version(1).build()))
            .toString());
  }
}
